using System;
using System.Linq;
using System.Reflection;
using Revora;
using Revora.Client;
using Revora.Database;
using Revora.Game;
using Revora.Network.GamePackets;
using Console=System.Console;
internal static partial class CheckCandidateArenaLifecycle {
    static string FreshTeamArenaSnapshot(GameState p,GameState[] players){return Convert.ToString(Sql(@"SELECT json_build_object('prior',@prior::json,'teams',(SELECT json_agg(r ORDER BY entityid) FROM teamarena r WHERE entityid=ANY(@uids)),'balls',(SELECT json_agg(r ORDER BY uid) FROM revora_exp_ball_days r WHERE uid=ANY(@uids)),'results',(SELECT json_agg(r ORDER BY id) FROM revora_team_arena_results r WHERE id IN(SELECT run FROM revora_team_arena_statistics WHERE uid=ANY(@uids))),'statistics',(SELECT json_agg(r ORDER BY run,uid) FROM revora_team_arena_statistics r WHERE uid=ANY(@uids)),'admissions',(SELECT json_agg(r ORDER BY run,uid) FROM revora_team_arena_admission_players r WHERE uid=ANY(@uids)))::text","prior",FreshEliteSnapshot(p,players,Convert.ToString(Sql("SELECT run FROM revora_fresh_elite_probe"))),"uids",players.Select(w=>(long)w.Entity.UID).ToArray()));}
    static void FreshTeamArenaSave(GameState p,GameState[] players,int stage){foreach(var who in players)Require(EntityTable.SaveEntity(who));Sql("UPDATE revora_fresh_team_arena_probe SET stage=@stage,snapshot=@snapshot","stage",stage,"snapshot",FreshTeamArenaSnapshot(p,players));}
    static void FreshTeamArenaJourney(string phase){
        bool prepare=phase.EndsWith("prepare"),earn=phase.EndsWith("earn"),claim=phase.EndsWith("claim");var p=FreshLoadSaved(true,true,true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);
        var list=new System.Collections.Generic.List<GameState>();foreach(int slot in new[]{1,2,3,0}){uint uid=Convert.ToUInt32(Sql("SELECT uid FROM revora_fresh_contributors WHERE slot=@slot","slot",slot));list.Add(FreshContributor(uid,Convert.ToString(Sql("SELECT name FROM revora_fresh_contributors WHERE slot=@slot","slot",slot))));}list.Add(p);var players=list.ToArray();var peer=players[3];Server.GamePool=players;Require(players.All(w=>!w.Fake && w.Account.State==AccountTable.AccountState.Player && !PirateFenced(w) && !w.Entity.Dead));


        Revora.Database.KnownPersons.LoadPartner(p);Revora.Database.KnownPersons.LoaderFriends(p);var mate=players[0];var other=players[2];var fighters=new[]{p,mate,peer,other};
        if(prepare){
            Require(FreshEliteSnapshot(p,players,Convert.ToString(Sql("SELECT run FROM revora_fresh_elite_probe")))==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_elite_probe WHERE stage=2")) && (bool)Sql("SELECT to_regclass('revora_fresh_team_arena_probe') IS NULL"));
            int store=Math.Max(0,p.Inventory.Count-39);var bank=p.Warehouses[Revora.Game.ConquerStructures.Warehouse.WarehouseID.DesertCity];Require(bank.Count+store<=60);FreshClassicTalk(p,1000,10011,0);
            foreach(var item in p.Inventory.Objects.Where(i=>i.Days==0).Take(store).ToArray()){var frame=new byte[172];Revora.Network.Writer.WriteUInt16(164,0,frame);Revora.Network.Writer.WriteUInt16(1102,2,frame);Revora.Network.Writer.WriteUInt32(10011,4,frame);frame[12]=1;frame[13]=10;Revora.Network.Writer.WriteUInt32(item.UID,18,frame);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,164,frame);Warehouse.Process(frame,p);Require(!p.Inventory.ContainsUID(item.UID) && bank.ContainsUID(item.UID));}
            Sql("CREATE TABLE revora_fresh_team_arena_probe(stage int NOT NULL,snapshot text);INSERT INTO revora_fresh_team_arena_probe VALUES(0,NULL)");FreshTeamArenaSave(p,players,0);
            DateTime day=new DateTime(2041,7,7,12,0,0,DateTimeKind.Local);Feature("ExperienceConsumables").GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>day));
            foreach(var who in new[]{mate,other}){Require(who.Entity.Level==50);uint initial=who.Entity.ConquerPoints;int balls=0;who.Entity.Teleport(1002,304,435);
                while(who.Entity.Level<70 && balls<30){day=new DateTime(2041,7,7,12,0,0,DateTimeKind.Local).AddDays(balls/10);var old=who.Inventory.Objects.Select(i=>i.UID).ToArray();CareerBuy(who,723700);var ball=who.Inventory.Objects.Single(i=>!old.Contains(i.UID));Require(ball.ID==723700);if(balls>0 && balls%10==0){day=day.AddDays(-1);byte level=who.Entity.Level;ulong xp=who.Entity.Experience;ItemHandler.UseItem(ball,who);Require(who.Entity.Level==level && who.Entity.Experience==xp && who.Inventory.ContainsUID(ball.UID));day=day.AddDays(1);}byte beforeLevel=who.Entity.Level;ulong beforeXp=who.Entity.Experience;ItemHandler.UseItem(ball,who);Require(!who.Inventory.ContainsUID(ball.UID) && (who.Entity.Level>beforeLevel || who.Entity.Experience>beforeXp));balls++;FreshTeamArenaSave(p,players,0);}
                Require(who.Entity.Level>=70 && initial-who.Entity.ConquerPoints==balls*27);Console.WriteLine("[fresh-team-arena] trained="+who.Entity.UID+" level="+who.Entity.Level+" balls="+balls+" cp="+(initial-who.Entity.ConquerPoints));
            }
            foreach(var who in fighters)who.Entity.Teleport(1002,408,330);FreshTeamArenaSave(p,players,1);
        }else{
            Require(FreshTeamArenaSnapshot(p,players)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_team_arena_probe")));
            if(earn){
                Require((int)Sql("SELECT stage FROM revora_fresh_team_arena_probe")==1 && fighters.All(w=>w.Entity.Level>=70));
                Action<GameState,uint,uint> team=(who,action,target)=>{var frame=new Revora.Network.GamePackets.Team{Type=action,UID=target}.ToArray();Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,frame.Length-8,frame);Revora.Network.GamePackets.Team.Process(frame,who);};
                team(p,Revora.Network.GamePackets.Team.Create,0);team(peer,Revora.Network.GamePackets.Team.Create,0);team(p,Revora.Network.GamePackets.Team.InviteRequest,mate.Entity.UID);team(mate,Revora.Network.GamePackets.Team.AcceptInvitation,p.Entity.UID);team(peer,Revora.Network.GamePackets.Team.InviteRequest,other.Entity.UID);team(other,Revora.Network.GamePackets.Team.AcceptInvitation,peer.Entity.UID);Require(p.Team.Teammates.Length==2 && peer.Team.Teammates.Length==2 && ReferenceEquals(p.Team,mate.Team) && ReferenceEquals(peer.Team,other.Team));
                DateTime now=new DateTime(2041,7,10,20,0,0,DateTimeKind.Utc);Feature("ArenaMatchLedger").GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));TeamQualifier.AcceptingNewBattles=true;TeamArenaClaimRequest(p,0,0);TeamArenaClaimRequest(peer,0,0);TeamQualifier.EngagePlayers();Require(ReferenceEquals(p.TeamArenaStatistic.PlayWith,peer));TeamArenaClaimRequest(p,3,1);TeamArenaClaimRequest(peer,3,1);TeamQualifier.VerifyAwaitingPeople();var group=p.TeamQualifierGroup;Require(group!=null && fighters.All(w=>ReferenceEquals(w.TeamQualifierGroup,group)));group.ImportTime=group.CreateTime=Time32.Now.AddSeconds(-13);foreach(var who in fighters){who.Attackable=true;who.CantAttack=Time32.Now.AddSeconds(-1);}int hits=0;
                foreach(var target in new[]{peer,other}){for(int n=0;n<300 && !target.Entity.Dead && !group.Done;n++){p.Entity.X=target.Entity.X;p.Entity.Y=(ushort)(target.Entity.Y+1);p.Screen.Add(target.Entity);target.Screen.Add(p.Entity);p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=target.Entity.UID,X=target.Entity.X,Y=target.Entity.Y,AttackType=Attack.Melee},p);hits++;}}
                Require(group.Done);group.DoneStamp=Time32.Now.AddSeconds(-6);var limit=DateTime.UtcNow.AddSeconds(10);do{TeamQualifier.CheckGroups();if(fighters.All(w=>w.TeamQualifierGroup==null))break;System.Threading.Thread.Sleep(50);}while(DateTime.UtcNow<limit);Require(fighters.All(w=>w.TeamQualifierGroup==null));
                foreach(var who in fighters){Require((long)Sql("SELECT count(*) FROM revora_team_arena_statistics WHERE uid=@uid AND won=@won","uid",(long)who.Entity.UID,"won",who==p || who==mate)==1);if(who.Entity.Dead){who.Entity.DeathStamp=Time32.Now.AddSeconds(-20);GeneralData.Revive(new Data(true){dwParam=0},who);}Require(!who.Entity.Dead && who.Entity.MapID==1002);team(who,Revora.Network.GamePackets.Team.ExitTeam,0);}
                FreshTeamArenaSave(p,players,2);Console.WriteLine("[fresh-team-arena] calculated-hits="+hits);
            }else{
                if(claim){Require((int)Sql("SELECT stage FROM revora_fresh_team_arena_probe")==2);foreach(var who in new[]{p,mate}){var old=who.Inventory.Objects.Select(i=>i.UID).ToArray();NobilityClaimPacket(who,305);var reward=who.Inventory.Objects.Single(i=>!old.Contains(i.UID));Require(reward.ID==1200001 && reward.Bound);uint blessing=who.Entity.HeavenBlessing;SoulClaimUse(who,reward);Require(!who.Inventory.ContainsUID(reward.UID) && who.Entity.HeavenBlessing==blessing+604800);}FreshTeamArenaSave(p,players,3);}else Require(phase.EndsWith("reload") && (int)Sql("SELECT stage FROM revora_fresh_team_arena_probe")==3);
                string saved=FreshTeamArenaSnapshot(p,players);foreach(var who in fighters){NobilityClaimPacket(who,305);NobilityClaimPacket(who,507);}Require(saved==FreshTeamArenaSnapshot(p,players));foreach(var who in new[]{p,mate})Require((long)Sql("SELECT count(*) FROM revora_way_of_heroes_claims WHERE uid=@uid AND stage_uid=305 AND NOT legacy","uid",(long)who.Entity.UID)==1);
                foreach(var who in players){var ids=(long[])Sql("SELECT coalesce(array_agg(uid ORDER BY uid),ARRAY[]::bigint[]) FROM items WHERE entityid=@uid AND position=0 AND warehouse=0 AND coalesce(inwardrobe,0)=0","uid",(long)who.Entity.UID);Require(ids.SequenceEqual(who.Inventory.Objects.Select(i=>(long)i.UID).OrderBy(id=>id)) && EntityTable.SaveEntity(who));}Require(saved==FreshTeamArenaSnapshot(p,players));
            }
        }
        Console.WriteLine("[career-process] "+phase+"-passed");Console.Out.Flush();if(prepare || earn || claim){Environment.Exit(0);return;}Server.CommandsAI("@close");throw new InvalidOperationException("Fresh Team Arena did not close.");
    }
}
